"""Replay double of `runlog.Run`: a finished 3-checkpoint snake run folder (budget 2,000;
21 evaluation points; checkpoints at 0, 50 and 100%).

`ReplayRun(record, episodes, evals, checkpoints)` serves any such parts; `from_recording` reads
them from a recording, and `renamed` derives another run of the same settings (the
`runlog.find_runs` fake uses both).
"""

import dataclasses
from pathlib import Path

from rllab.core import EpisodeResult
from rllab.runlog import Checkpoint, EvalPoint, RunRecord


class ReplayRun:
    def __init__(self, record, episodes, evals, checkpoints) -> None:
        self.record: RunRecord = record
        self._episodes: list[EpisodeResult] = list(episodes)
        self._evals: list[EvalPoint] = list(evals)
        self._checkpoints: list[Checkpoint] = list(checkpoints)

    def episodes(self) -> list[EpisodeResult]:
        return list(self._episodes)

    def evals(self) -> list[EvalPoint]:
        return list(self._evals)

    def checkpoints(self) -> list[Checkpoint]:
        return list(self._checkpoints)


def from_recording(fx, rec) -> ReplayRun:
    return ReplayRun(
        fx.decode(RunRecord, rec["record"]),
        [fx.decode(EpisodeResult, e) for e in rec["episodes"]],
        [fx.decode(EvalPoint, e) for e in rec["evals"]],
        [fx.decode(Checkpoint, c) for c in rec["checkpoints"]],
    )


def renamed(run: ReplayRun, seed: int, status: str, root: Path, scale: float) -> ReplayRun:
    """The same run with seed `seed`, its name, `status`, a folder under `root`, and every
    evaluation score and measure times `scale`."""
    old = run.record.config
    name = f"{old.world}-{old.variant}-s{seed}"
    path = Path(root) / old.world / old.variant / name
    config = dataclasses.replace(old, name=name, seed=seed)
    record = dataclasses.replace(run.record, config=config, status=status, path=path)
    evals = [
        EvalPoint(
            p.step,
            {k: v * scale for k, v in p.scores.items()},
            {k: v * scale for k, v in p.measures.items()},
        )
        for p in run.evals()
    ]
    checkpoints = [
        dataclasses.replace(c, run=name, path=path / "checkpoints" / c.path.name)
        for c in run.checkpoints()
    ]
    return ReplayRun(record, run.episodes(), evals, checkpoints)


def build(fx, case: str) -> ReplayRun:
    return from_recording(fx, fx.recording(case))

